UPDATE transactions
SET status = #{status}
WHERE transaction_id = #{transactionId}

UPDATE transactions
SET status = #{status},
balance_after = #{balanceAfter},
completed_at = #{completedAt}
WHERE transaction_id = #{transactionId}

mapper.select:
SELECT t.transaction_id AS transactionId, CASE WHEN t.type = 'TRANSFER_OUT' THEN 'TRANSFER' ELSE t.type END AS type, CASE WHEN t.type = 'CHARGE' THEN 'IN' ELSE 'OUT' END AS direction, CASE t.type WHEN 'CHARGE' THEN b.bank_name WHEN 'PAYMENT' THEN m.name WHEN 'TRANSFER_OUT' THEN r.holder_name END AS title, t.amount AS amount, t.status AS status, re.risk_level AS riskLevel, t.created_at AS occurredAt FROM transactions t JOIN wallets w ON w.wallet_id = t.wallet_id LEFT JOIN recipients r ON r.recipient_id = t.recipient_id LEFT JOIN merchants m ON m.merchant_id = t.merchant_id LEFT JOIN linked_accounts la ON la.account_id = t.account_id LEFT JOIN banks b ON b.bank_code = la.bank_code LEFT JOIN risk_evaluations re ON re.transaction_id = t.transaction_id WHERE w.user_id = #{wardId}
AND t.type = #{type}
AND ( COALESCE(r.holder_name, m.name, b.bank_name) LIKE CONCAT('%', #{keyword}, '%') OR CAST(t.amount AS CHAR) LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY t.created_at DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM transactions t JOIN wallets w ON w.wallet_id = t.wallet_id LEFT JOIN recipients r ON r.recipient_id = t.recipient_id LEFT JOIN merchants m ON m.merchant_id = t.merchant_id LEFT JOIN linked_accounts la ON la.account_id = t.account_id LEFT JOIN banks b ON b.bank_code = la.bank_code WHERE w.user_id = #{wardId}
AND t.type = #{type}
AND ( COALESCE(r.holder_name, m.name, b.bank_name) LIKE CONCAT('%', #{keyword}, '%') OR CAST(t.amount AS CHAR) LIKE CONCAT('%', #{keyword}, '%') )
